func parseConfig(data string) (*Config, error) {
	cfg := defaultConfig()
	scanner := bufio.NewScanner(strings.NewReader(data))
	currentRule := ""

	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			tableName := strings.TrimSpace(line[1 : len(line)-1])
			if strings.HasPrefix(tableName, "rule.") {
				currentRule = strings.TrimPrefix(tableName, "rule.")
				if _, exists := cfg.Rules[currentRule]; !exists {
					cfg.Rules[currentRule] = RuleConfig{}
				}
			} else if tableName == "rule" {
				currentRule = ""
			} else {
				return nil, fmt.Errorf("toml: line %d: unknown table %s", lineNum, tableName)
			}
			continue
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("toml: line %d: expected '=' in key-value pair", lineNum)
		}

		key := strings.TrimSpace(parts[0])
		valStr := strings.TrimSpace(parts[1])

		val, err := parseValue(valStr)
		if err != nil {
			return nil, fmt.Errorf("toml: line %d: %v", lineNum, err)
		}

		if currentRule == "" {
			switch strings.ToLower(key) {
			case "severity":
				if s, ok := val.(string); ok {
					cfg.Severity = s
				}
			case "confidence":
				if f, ok := toFloat(val); ok {
					cfg.Confidence = f
				}
			case "errorcode":
				if i, ok := toInt(val); ok {
					cfg.ErrorCode = i
				}
			case "warningcode":
				if i, ok := toInt(val); ok {
					cfg.WarningCode = i
				}
			case "ignoregeneratedheader":
				if b, ok := val.(bool); ok {
					cfg.IgnoreGeneratedHeader = b
				}
			}
		} else {
			rc := cfg.Rules[currentRule]
			switch strings.ToLower(key) {
			case "disabled":
				if b, ok := val.(bool); ok {
					rc.Disabled = b
				}
			case "severity":
				if s, ok := val.(string); ok {
					rc.Severity = s
				}
			case "arguments":
				if arr, ok := val.([]interface{}); ok {
					rc.Arguments = arr
				}
			case "exclude":
				if arr, ok := val.([]interface{}); ok {
					var excs []string
					for _, item := range arr {
						if s, ok := item.(string); ok {
							excs = append(excs, s)
						}
					}
					rc.Exclude = excs
				}
			}
			cfg.Rules[currentRule] = rc
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	return cfg, nil
}

func parseValue(s string) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "true" {
		return true, nil
	}
	if s == "false" {
		return false, nil
	}
	if strings.HasPrefix(s, `"`) && strings.HasSuffix(s, `"`) && len(s) >= 2 {
		return s[1 : len(s)-1], nil
	}
	if strings.HasPrefix(s, `'`) && strings.HasSuffix(s, `'`) && len(s) >= 2 {
		return s[1 : len(s)-1], nil
	}
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner := strings.TrimSpace(s[1 : len(s)-1])
		if inner == "" {
			return []interface{}{}, nil
		}
		items, err := parseArrayItems(inner)
		if err != nil {
			return nil, err
		}
		var res []interface{}
		for _, itemStr := range items {
			v, err := parseValue(itemStr)
			if err != nil {
				return nil, err
			}
			res = append(res, v)
		}
		return res, nil
	}
	if i, err := strconv.Atoi(s); err == nil {
		return i, nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	return nil, fmt.Errorf("invalid value %s", s)
}

func parseArrayItems(s string) ([]string, error) {
	var items []string
	var current strings.Builder
	inQuote := false
	quoteChar := byte(0)
	bracketDepth := 0

	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inQuote {
			current.WriteByte(ch)
			if ch == quoteChar && (i == 0 || s[i-1] != '\\') {
				inQuote = false
			}
			continue
		}

		if ch == '"' || ch == '\'' {
			inQuote = true
			quoteChar = ch
			current.WriteByte(ch)
			continue
		}

		if ch == '[' {
			bracketDepth++
			current.WriteByte(ch)
			continue
		}

		if ch == ']' {
			bracketDepth--
			current.WriteByte(ch)
			continue
		}

		if ch == ',' && bracketDepth == 0 {
			items = append(items, strings.TrimSpace(current.String()))
			current.Reset()
			continue
		}

		current.WriteByte(ch)
	}

	if current.Len() > 0 {
		trimmed := strings.TrimSpace(current.String())
		if trimmed != "" {
			items = append(items, trimmed)
		}
	}

	return items, nil
}

func toFloat(v interface{}) (float64, bool) {
	switch val := v.(type) {
	case float64:
		return val, true
	case int:
		return float64(val), true
	}
	return 0, false
}

func toInt(v interface{}) (int, bool) {
	switch val := v.(type) {
	case int:
		return val, true
	case float64:
		return int(val), true
	}
	return 0, false
}
EOF"}

