type StylishFormatter struct{}

func (f *StylishFormatter) Format(failures []Failure, config *Config) (string, error) {
	if len(failures) == 0 {
		return "", nil
	}

	var sb strings.Builder
	byFile := make(map[string][]Failure)
	var fileOrder []string

	for _, failure := range failures {
		fn := failure.Position.Start.Filename
		if _, exists := byFile[fn]; !exists {
			fileOrder = append(fileOrder, fn)
		}
		byFile[fn] = append(byFile[fn], failure)
	}

	errorsCount := 0
	warningsCount := 0

	for _, fn := range fileOrder {
		fileFailures := byFile[fn]
		sb.WriteString(fn + "\n")

		maxPosLen := 0
		maxRuleLen := 0

		for _, failure := range fileFailures {
			posStr := fmt.Sprintf("(%d, %d)", failure.Position.Start.Line, failure.Position.Start.Column)
			if len(posStr) > maxPosLen {
				maxPosLen = len(posStr)
			}
			ruleUrl := fmt.Sprintf("https://revive.run/r#%s", failure.RuleName)
			if len(ruleUrl) > maxRuleLen {
				maxRuleLen = len(ruleUrl)
			}
		}

		for _, failure := range fileFailures {
			if failure.Severity == SeverityError {
				errorsCount++
			} else {
				warningsCount++
			}

			posStr := fmt.Sprintf("(%d, %d)", failure.Position.Start.Line, failure.Position.Start.Column)
			ruleUrl := fmt.Sprintf("https://revive.run/r#%s", failure.RuleName)

			posPad := strings.Repeat(" ", maxPosLen-len(posStr)+2)
			rulePad := strings.Repeat(" ", maxRuleLen-len(ruleUrl)+2)

			sb.WriteString(fmt.Sprintf("  %s%s%s%s%s\n", posStr, posPad, ruleUrl, rulePad, failure.Failure))
		}
		sb.WriteString("\n")
	}

	total := len(failures)
	probStr := "problem"
	if total != 1 {
		probStr = "problems"
	}

