// CheckstyleFormatter
type CheckstyleFormatter struct{}

type checkstyleXML struct {
	XMLName xml.Name         `xml:"checkstyle"`
	Version string           `xml:"version,attr"`
	Files   []checkstyleFile `xml:"file"`
}

type checkstyleFile struct {
	Name   string            `xml:"name,attr"`
	Errors []checkstyleError `xml:"error"`
}

type checkstyleError struct {
	Line     int    `xml:"line,attr"`
	Column   int    `xml:"column,attr"`
	Message  string `xml:"message,attr"`
	Severity string `xml:"severity,attr"`
	Source   string `xml:"source,attr"`
}

func (f *CheckstyleFormatter) Format(failures []Failure, config *Config) (string, error) {
	byFile := make(map[string][]Failure)
	var fileOrder []string

	for _, failure := range failures {
		fn := failure.Position.Start.Filename
		if _, exists := byFile[fn]; !exists {
			fileOrder = append(fileOrder, fn)
		}
		byFile[fn] = append(byFile[fn], failure)
	}

	var xmlFiles []checkstyleFile
	for _, fn := range fileOrder {
		var xmlErrors []checkstyleError
		for _, failure := range byFile[fn] {
			confStr := fmt.Sprintf("%v", failure.Confidence)
			if failure.Confidence == 1.0 {
				confStr = "1"
			}
			msg := fmt.Sprintf("%s (confidence %s)", failure.Failure, confStr)
			xmlErrors = append(xmlErrors, checkstyleError{
				Line:     failure.Position.Start.Line,
				Column:   failure.Position.Start.Column,
				Message:  msg,
				Severity: string(failure.Severity),
				Source:   "revive/" + failure.RuleName,
			})
		}
		xmlFiles = append(xmlFiles, checkstyleFile{
			Name:   fn,
			Errors: xmlErrors,
		})
	}

	cs := checkstyleXML{
		Version: "5.0",
		Files:   xmlFiles,
	}

	out, err := xml.MarshalIndent(cs, "", "  ")
	if err != nil {
		return "", err
	}

	var sb strings.Builder
	sb.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n")
	sb.Write(out)
	sb.WriteString("\n")
	return sb.String(), nil
}

// SARIFFormatter
type SARIFFormatter struct{}

func (f *SARIFFormatter) Format(failures []Failure, config *Config) (string, error) {
	ruleMap := make(map[string]string)
	var results []map[string]interface{}

	for _, failure := range failures {
		ruleMap[failure.RuleName] = string(failure.Severity)

		result := map[string]interface{}{
			"level":  string(failure.Severity),
			"ruleId": failure.RuleName,
			"message": map[string]interface{}{
				"text": failure.Failure,
			},
			"locations": []map[string]interface{}{
				{
					"physicalLocation": map[string]interface{}{
						"artifactLocation": map[string]interface{}{
							"uri": failure.Position.Start.Filename,
						},
						"region": map[string]interface{}{
							"startLine":   failure.Position.Start.Line,
							"startColumn": failure.Position.Start.Column,
						},
					},
				},
			},
		}
		results = append(results, result)
	}

	if results == nil {
		results = []map[string]interface{}{}
	}

	var rules []map[string]interface{}
	var sortedRuleIds []string
	for r := range ruleMap {
		sortedRuleIds = append(sortedRuleIds, r)
	}
	sort.Strings(sortedRuleIds)
	if len(sortedRuleIds) == 0 {
		// default rule if empty
		sortedRuleIds = append(sortedRuleIds, "indent-error-flow")
		ruleMap["indent-error-flow"] = "warning"
	}

	for _, r := range sortedRuleIds {
		rules = append(rules, map[string]interface{}{
			"id":      r,
			"helpUri": fmt.Sprintf("https://revive.run/r#%s", r),
			"properties": map[string]interface{}{
				"severity": ruleMap[r],
			},
		})
	}

	sarif := map[string]interface{}{
		"version": "2.1.0",
		"runs": []map[string]interface{}{
			{
				"tool": map[string]interface{}{
					"driver": map[string]interface{}{
						"name":           "revive",
						"informationUri": "https://revive.run",
						"rules":          rules,
					},
				},
				"results": results,
			},
		},
	}

	out, err := json.MarshalIndent(sarif, "", "  ")
	if err != nil {
		return "", err
	}
	return string(out) + "\n", nil
}
EOF"}

