type UselessBreakRule struct{}

func (r *UselessBreakRule) Name() string { return "useless-break" }
func (r *UselessBreakRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
