	ast.Inspect(file.AST, func(n ast.Node) bool {
		caseClause, ok := n.(*ast.CaseClause)
		if !ok || len(caseClause.Body) == 0 {
			return true
		}

		lastStmt := caseClause.Body[len(caseClause.Body)-1]
		if branch, ok := lastStmt.(*ast.BranchStmt); ok && branch.Tok == token.BREAK && branch.Label == nil {
			failures = append(failures, Failure{
				Failure:    "useless break in case clause",
				RuleName:   r.Name(),
				Category:   "",
				Position:   file.NodePosition(branch),
