func (r *LineLengthLimitRule) Name() string { return "line-length-limit" }
func (r *LineLengthLimitRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	limit := 80
	if len(args) > 0 {
		if l, ok := toInt(args[0]); ok {
			limit = l
		}
	}

	lines := strings.Split(file.Content, "\n")
	for i, line := range lines {
		if len(line) > limit {
			failures = append(failures, Failure{
				Failure:  fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
				RuleName: r.Name(),
				Category: "style",
				Position: Position{
					Start: Pos{Filename: file.Name, Line: i + 1, Column: 1},
					End:   Pos{Filename: file.Name, Line: i + 1, Column: len(line)},
				},
				Confidence: 1.0,
			})
		}
	}
	return failures
}

