	var failures []Failure
	limit := 4
	if len(args) > 0 {
		if l, ok := toInt(args[0]); ok {
			limit = l
		}
	}

	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type.Params == nil {
			return true
		}

		count := 0
		for _, param := range fn.Type.Params.List {
			if len(param.Names) > 0 {
				count += len(param.Names)
			} else {
				count++
			}
		}

		if count > limit {
			failures = append(failures, Failure{
				Failure:    fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", limit, count),
				RuleName:   r.Name(),
				Category:   "",
				Position:   file.NodePosition(fn.Name),
				Confidence: 1.0,
