		tagVal, _ := strconv.Unquote(field.Tag.Value)
		if !strings.Contains(tagVal, ":\"") {
			failures = append(failures, Failure{
				Failure:    "malformed tag",
				RuleName:   r.Name(),
				Category:   "",
				Position:   file.NodePosition(field.Tag),
