package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"unicode"
)

type Severity string

const (
	SeverityWarning Severity = "warning"
	SeverityError   Severity = "error"
)

type Pos struct {
	Filename string `json:"Filename"`
	Offset   int    `json:"Offset"`
	Line     int    `json:"Line"`
	Column   int    `json:"Column"`
}

type Position struct {
	Start Pos `json:"Start"`
	End   Pos `json:"End"`
}

type Failure struct {
	Failure         string   `json:"Failure"`
	RuleName        string   `json:"RuleName"`
	Category        string   `json:"Category"`
	Position        Position `json:"Position"`
	Confidence      float64  `json:"Confidence"`
	Severity        Severity `json:"Severity"`
	ReplacementLine string   `json:"ReplacementLine"`
}

type Rule interface {
	Name() string
	Apply(file *File, args []interface{}) []Failure
}

type File struct {
	Name    string
	FSet    *token.FileSet
	AST     *ast.File
	Content string
}

func (f *File) Position(pos token.Pos) Pos {
	p := f.FSet.Position(pos)
	return Pos{
		Filename: f.Name,
		Offset:   p.Offset,
		Line:     p.Line,
		Column:   p.Column,
	}
}

func (f *File) NodePosition(node ast.Node) Position {
	start := f.Position(node.Pos())
	end := f.Position(node.End())
	return Position{Start: start, End: end}
}

// Registry of all rules
var ruleRegistry = make(map[string]Rule)

func registerRule(r Rule) {
	ruleRegistry[r.Name()] = r
}

func init() {
	registerRule(&PackageCommentsRule{})
	registerRule(&VarDeclarationRule{})
