	registerRule(&VarNamingRule{})
	registerRule(&ErrorStringsRule{})
	registerRule(&UseErrorsNewRule{})
	registerRule(&BoolLiteralInExprRule{})
	registerRule(&CallToGCRule{})
	registerRule(&DeepExitRule{})
	registerRule(&GetReturnRule{})
	registerRule(&IncrementDecrementRule{})
	registerRule(&RangeValInClosureRule{})
	registerRule(&UnnecessaryStmtRule{})
	registerRule(&UseAnyRule{})
	registerRule(&UselessBreakRule{})
	registerRule(&AddConstantRule{})
	registerRule(&LineLengthLimitRule{})
	registerRule(&ArgumentLimitRule{})
	registerRule(&FunctionResultLimitRule{})
	registerRule(&FunctionLengthRule{})
	registerRule(&FileLengthLimitRule{})
