// 10. VarNamingRule
type VarNamingRule struct{}

func (r *VarNamingRule) Name() string { return "var-naming" }
func (r *VarNamingRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		if valSpec, ok := n.(*ast.ValueSpec); ok {
			for _, name := range valSpec.Names {
				if strings.Contains(name.Name, "_") && name.Name != "_" && !strings.HasPrefix(name.Name, "_") {
					suggested := snakeToCamel(name.Name)
					failures = append(failures, Failure{
						Failure:    fmt.Sprintf("don't use underscores in Go names; var %s should be %s", name.Name, suggested),
						RuleName:   r.Name(),
						Category:   "naming",
						Position:   file.NodePosition(name),
						Confidence: 0.9,
					})
				}
			}
		}
		return true
	})
	return failures
}

func snakeToCamel(s string) string {
	parts := strings.Split(s, "_")
	var sb strings.Builder
	for i, p := range parts {
		if i == 0 {
			sb.WriteString(p)
		} else {
			sb.WriteString(strings.Title(p))
		}
	}
	return sb.String()
}

// 11. ErrorStringsRule
type ErrorStringsRule struct{}

func (r *ErrorStringsRule) Name() string { return "error-strings" }
func (r *ErrorStringsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}

		isErrFunc := false
		if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if (id.Name == "errors" && sel.Sel.Name == "New") || (id.Name == "fmt" && sel.Sel.Name == "Errorf") {
					isErrFunc = true
				}
			}
		}

		if isErrFunc {
			if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
				str, err := strconv.Unquote(lit.Value)
				if err == nil && len(str) > 0 {
					firstRune := []rune(str)[0]
					lastRune := []rune(str)[len([]rune(str))-1]
					if unicode.IsUpper(firstRune) || lastRune == '.' || lastRune == '!' || lastRune == '\n' {
						failures = append(failures, Failure{
							Failure:    "error strings should not be capitalized or end with punctuation or a newline",
							RuleName:   r.Name(),
							Category:   "errors",
							Position:   file.NodePosition(lit),
							Confidence: 0.8,
						})
					}
				}
			}
		}
		return true
	})
	return failures
}

