				RuleName:   r.Name(),
				Category:   "imports",
				Position:   file.NodePosition(imp),
				Confidence: 1.0,
			})
		}
	}
	return failures
}

// 5. BlankImportsRule
type BlankImportsRule struct{}

func (r *BlankImportsRule) Name() string { return "blank-imports" }
func (r *BlankImportsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	if file.AST.Name.Name == "main" || strings.HasSuffix(file.Name, "_test.go") {
		return failures
