// 15. DeepExitRule
type DeepExitRule struct{}

func (r *DeepExitRule) Name() string { return "deep-exit" }
func (r *DeepExitRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}

		if fn.Name.Name == "main" || fn.Name.Name == "init" {
			return true
		}

		ast.Inspect(fn.Body, func(bn ast.Node) bool {
			call, ok := bn.(*ast.CallExpr)
			if !ok {
				return true
			}
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				if id, ok := sel.X.(*ast.Ident); ok && id.Name == "os" && sel.Sel.Name == "Exit" {
					failures = append(failures, Failure{
						Failure:    "calls to os.Exit only in main() or init() functions",
						RuleName:   r.Name(),
						Category:   "bad practice",
						Position:   file.NodePosition(call),
						Confidence: 1.0,
					})
				}
			}
			return true
		})
		return true
	})
	return failures
}

// 16. GetReturnRule
type GetReturnRule struct{}

func (r *GetReturnRule) Name() string { return "get-return" }
func (r *GetReturnRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}

		if strings.HasPrefix(fn.Name.Name, "get") || strings.HasPrefix(fn.Name.Name, "Get") {
			if fn.Type.Results == nil || len(fn.Type.Results.List) == 0 {
				failures = append(failures, Failure{
