// 23. LineLengthLimitRule
type LineLengthLimitRule struct{}

func (r *LineLengthLimitRule) Name() string { return "line-length-limit" }
func (r *LineLengthLimitRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	limit := 80
	if len(args) > 0 {
		if l, ok := toInt(args[0]); ok {
			limit = l
		}
	}

	lines := strings.Split(file.Content, "\n")
	for i, line := range lines {
		if len(line) > limit {
			failures = append(failures, Failure{
				Failure:  fmt.Sprintf("line is %d characters, out of limit %d", len(line), limit),
				RuleName: r.Name(),
				Category: "style",
				Position: Position{
					Start: Pos{Filename: file.Name, Line: i + 1, Column: 1},
					End:   Pos{Filename: file.Name, Line: i + 1, Column: len(line)},
				},
				Confidence: 1.0,
			})
		}
	}
	return failures
}

// 24. ArgumentLimitRule
type ArgumentLimitRule struct{}

func (r *ArgumentLimitRule) Name() string { return "argument-limit" }
func (r *ArgumentLimitRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	limit := 4
	if len(args) > 0 {
		if l, ok := toInt(args[0]); ok {
			limit = l
		}
	}

	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type.Params == nil {
			return true
		}

		count := 0
		for _, param := range fn.Type.Params.List {
			if len(param.Names) > 0 {
				count += len(param.Names)
			} else {
				count++
			}
		}

		if count > limit {
			failures = append(failures, Failure{
				Failure:    fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", limit, count),
				RuleName:   r.Name(),
				Category:   "",
				Position:   file.NodePosition(fn.Name),
				Confidence: 1.0,
			})
		}
		return true
	})
	return failures
}

