type ReceiverNamingRule struct{}

func (r *ReceiverNamingRule) Name() string { return "receiver-naming" }
func (r *ReceiverNamingRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	receivers := make(map[string]string)
	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
			return true
		}

		recvField := fn.Recv.List[0]
		if len(recvField.Names) == 0 {
			return true
		}

		recvName := recvField.Names[0].Name
		typeName := exprString(recvField.Type)

		if prev, ok := receivers[typeName]; ok {
			if prev != recvName {
				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", recvName, prev, typeName),
					RuleName:   r.Name(),
					Category:   "naming",
					Position:   file.NodePosition(recvField.Names[0]),
					Confidence: 1.0,
				})
			}
		} else {
			receivers[typeName] = recvName
		}
		return true
	})
	return failures
}

type ModifiesValueReceiverRule struct{}

func (r *ModifiesValueReceiverRule) Name() string { return "modifies-value-receiver" }
func (r *ModifiesValueReceiverRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 || fn.Body == nil {
			return true
		}

		recvField := fn.Recv.List[0]
		if _, ok := recvField.Type.(*ast.StarExpr); ok {
			return true // pointer receiver is fine
		}

		if len(recvField.Names) == 0 {
			return true
		}
		recvName := recvField.Names[0].Name

		ast.Inspect(fn.Body, func(bn ast.Node) bool {
			assign, ok := bn.(*ast.AssignStmt)
			if !ok {
				return true
			}
			for _, lhs := range assign.Lhs {
				if sel, ok := lhs.(*ast.SelectorExpr); ok {
					if id, ok := sel.X.(*ast.Ident); ok && id.Name == recvName {
						failures = append(failures, Failure{
							Failure:    "suspicious assignment to a by-value method receiver",
							RuleName:   r.Name(),
							Category:   "",
							Position:   file.NodePosition(assign),
							Confidence: 1.0,
						})
					}
				}
			}
			return true
		})
		return true
	})
	return failures
}

type StringOfIntRule struct{}

func (r *StringOfIntRule) Name() string { return "string-of-int" }
