{"command":"cat <<'EOF' > lint.go
package main

import (
	"fmt"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type LintEngine struct {
	Config   *Config
	Excludes []string
}

func NewLintEngine(cfg *Config, excludes []string) *LintEngine {
	return &LintEngine{
		Config:   cfg,
		Excludes: excludes,
	}
}

var defaultRulesList = []string{
	"blank-imports",
	"context-as-argument",
	"context-keys-type",
	"dot-imports",
	"error-naming",
	"error-return",
	"error-strings",
	"errorf",
	"exported",
	"if-return",
	"increment-decrement",
	"indent-error-flow",
	"package-comments",
	"range",
	"receiver-naming",
	"time-naming",
	"unexported-return",
	"var-declaration",
	"var-naming",
	"unused-parameter",
	"unreachable-code",
}

func (e *LintEngine) Lint(paths []string) ([]Failure, error) {
	files, err := e.resolveFiles(paths)
	if err != nil {
		return nil, err
	}

	var allFailures []Failure

	for _, path := range files {
		contentBytes, err := os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("cannot read file %s: %v", path, err)
		}
		content := string(contentBytes)

		// Check generated header
		if !e.Config.IgnoreGeneratedHeader && isGenerated(content) {
			continue
		}

		fset := token.NewFileSet()
		node, parseErr := parser.ParseFile(fset, path, content, parser.ParseComments)
		if parseErr != nil {
			// Format parser error message
			// e.g. testdir/syntax_error.go:3:11: invalid file testdir/syntax_error.go: testdir/syntax_error.go:3:11: expected ')', found '{'
			var pLine, pCol int
			if errList, ok := parseErr.(parser.ErrorList); ok && len(errList) > 0 {
				pLine = errList[0].Pos.Line
				pCol = errList[0].Pos.Column
			} else {
				pLine = 1
				pCol = 1
			}
			msg := fmt.Sprintf("%s:%d:%d: invalid file %s: %v", path, pLine, pCol, path, parseErr)
			fmt.Println(msg)
			continue
		}

		fileObj := &File{
			Name:    path,
			FSet:    fset,
			AST:     node,
			Content: content,
		}

		directives := parseDirectives(fileObj)

		// Determine active rules
		var activeRules map[string]RuleConfig
		if len(e.Config.Rules) > 0 {
			activeRules = e.Config.Rules
		} else {
			activeRules = make(map[string]RuleConfig)
			for _, rName := range defaultRulesList {
				activeRules[rName] = RuleConfig{}
			}
		}

		for ruleName, rCfg := range activeRules {
			if rCfg.Disabled {
				continue
			}

			rule, exists := ruleRegistry[ruleName]
			if !exists {
				return nil, fmt.Errorf("initializing revive - getting lint rules: cannot find rule: %s", ruleName)
			}

			// Check rule-level exclude
			if matchAnyPattern(path, rCfg.Exclude) {
				continue
			}

			ruleFailures := rule.Apply(fileObj, rCfg.Arguments)
			for _, f := range ruleFailures {
				// Set severity
				if rCfg.Severity != "" {
					f.Severity = Severity(rCfg.Severity)
				} else if e.Config.Severity != "" {
					f.Severity = Severity(e.Config.Severity)
				} else {
					f.Severity = SeverityWarning
				}

				// Check confidence threshold
				if f.Confidence < e.Config.Confidence {
					continue
				}

				// Check directives
				if isDisabled(f, directives) {
					continue
				}

				allFailures = append(allFailures, f)
			}
		}
	}

	// Sort failures
	sort.Slice(allFailures, func(i, j int) bool {
		if allFailures[i].Position.Start.Filename != allFailures[j].Position.Start.Filename {
			return allFailures[i].Position.Start.Filename < allFailures[j].Position.Start.Filename
		}
		if allFailures[i].Position.Start.Line != allFailures[j].Position.Start.Line {
			return allFailures[i].Position.Start.Line < allFailures[j].Position.Start.Line
		}
		if allFailures[i].Position.Start.Column != allFailures[j].Position.Start.Column {
			return allFailures[i].Position.Start.Column < allFailures[j].Position.Start.Column
		}
		if allFailures[i].RuleName != allFailures[j].RuleName {
			return allFailures[i].RuleName < allFailures[j].RuleName
		}
		return allFailures[i].Failure < allFailures[j].Failure
	})

	return allFailures, nil
}

func (e *LintEngine) resolveFiles(paths []string) ([]string, error) {
	var fileList []string
	visited := make(map[string]bool)

	for _, p := range paths {
		cleanP := filepath.Clean(p)
		if strings.HasSuffix(p, "/...") || strings.HasSuffix(p, "...") {
			baseDir := strings.TrimSuffix(p, "/...")
			baseDir = strings.TrimSuffix(baseDir, "...")
			if baseDir == "" {
				baseDir = "."
			}
			err := filepath.Walk(baseDir, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if !info.IsDir() && strings.HasSuffix(path, ".go") {
					if !e.isExcluded(path) && !visited[path] {
						visited[path] = true
						fileList = append(fileList, path)
					}
				}
				return nil
			})
			if err != nil {
				return nil, err
			}
		} else {
			info, err := os.Stat(p)
			if err != nil {
				return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: go/build: go list %s: no such file or directory", p)
			}

			if info.IsDir() {
				entries, err := os.ReadDir(p)
				if err != nil {
					return nil, err
				}
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") {
						fullPath := filepath.Join(p, entry.Name())
						if !e.isExcluded(fullPath) && !visited[fullPath] {
							visited[fullPath] = true
							fileList = append(fileList, fullPath)
						}
					}
				}
			} else if strings.HasSuffix(p, ".go") {
				if !e.isExcluded(p) && !visited[p] {
					visited[p] = true
					fileList = append(fileList, p)
				}
			}
		}
	}

	return fileList, nil
}

func (e *LintEngine) isExcluded(path string) bool {
	return matchAnyPattern(path, e.Excludes)
}

func matchAnyPattern(path string, patterns []string) bool {
	for _, pat := range patterns {
		if strings.HasSuffix(pat, "/...") {
			prefix := strings.TrimSuffix(pat, "/...")
			if strings.HasPrefix(path, prefix) {
				return true
			}
		} else if matched, _ := filepath.Match(pat, path); matched {
			return true
		} else if matched, _ := filepath.Match(pat, filepath.Base(path)); matched {
			return true
		} else if path == pat {
			return true
		}
	}
	return false
}

func isGenerated(content string) bool {
	lines := strings.Split(content, "\n")
	for i, line := range lines {
		if i > 10 { // check top 10 lines
			break
		}
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "//") || strings.HasPrefix(line, "/*") {
			if strings.Contains(line, "Code generated by") && strings.Contains(line, "DO NOT EDIT.") {
				return true
			}
		}
	}
	return false
}
EOF"}

