package main

import (
	"strings"
)

type Directive struct {
	Action   string // disable, enable, disable-line, disable-next-line
	RuleName string // "" for all
	Line     int
}

func parseDirectives(file *File) []Directive {
	var directives []Directive
	if file.AST == nil || file.AST.Comments == nil {
		return directives
	}

	for _, commentGroup := range file.AST.Comments {
		for _, comment := range commentGroup.List {
			text := strings.TrimSpace(comment.Text)
			prefix := ""
			if strings.HasPrefix(text, "//revive:") {
				prefix = "//revive:"
			} else if strings.HasPrefix(text, "/*revive:") && strings.HasSuffix(text, "*/") {
				prefix = "/*revive:"
				text = strings.TrimSuffix(text, "*/")
			} else {
				continue
			}

			directiveBody := strings.TrimSpace(strings.TrimPrefix(text, prefix))
			parts := strings.SplitN(directiveBody, ":", 2)
			action := parts[0]
			ruleName := ""
			if len(parts) == 2 {
				ruleName = strings.TrimSpace(parts[1])
			}

			pos := file.Position(comment.Pos())
			directives = append(directives, Directive{
				Action:   action,
				RuleName: ruleName,
				Line:     pos.Line,
			})
		}
	}
	return directives
}

func isDisabled(failure Failure, directives []Directive) bool {
	line := failure.Position.Start.Line
	rule := failure.RuleName

	disabledGlobal := false
