// 1. PackageCommentsRule
type PackageCommentsRule struct{}

func (r *PackageCommentsRule) Name() string { return "package-comments" }
func (r *PackageCommentsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	pkgName := file.AST.Name.Name
	if file.AST.Doc == nil || len(file.AST.Doc.List) == 0 {
		failures = append(failures, Failure{
			Failure:    "should have a package comment",
			RuleName:   r.Name(),
			Category:   "comments",
			Position:   file.NodePosition(file.AST.Name),
			Confidence: 1.0,
		})
	} else {
		comment := strings.TrimSpace(file.AST.Doc.Text())
		expectedPrefix := fmt.Sprintf("Package %s", pkgName)
		if !strings.HasPrefix(comment, expectedPrefix) {
			failures = append(failures, Failure{
				Failure:    fmt.Sprintf("package comment should be of the form \"Package %s ...\"", pkgName),
				RuleName:   r.Name(),
				Category:   "comments",
				Position:   file.NodePosition(file.AST.Doc),
				Confidence: 1.0,
			})
		}
	}
	return failures
}

// 2. VarDeclarationRule
type VarDeclarationRule struct{}

func (r *VarDeclarationRule) Name() string { return "var-declaration" }
func (r *VarDeclarationRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		genDecl, ok := n.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.VAR {
			return true
		}

		for _, spec := range genDecl.Specs {
			valueSpec, ok := spec.(*ast.ValueSpec)
			if !ok || valueSpec.Type == nil || len(valueSpec.Values) == 0 {
				continue
			}

			for i, val := range valueSpec.Values {
				if i >= len(valueSpec.Names) {
					break
				}
				name := valueSpec.Names[i].Name

				// Check zero value
				if basic, ok := val.(*ast.BasicLit); ok {
					if (basic.Kind == token.INT || basic.Kind == token.FLOAT) && basic.Value == "0" {
						failures = append(failures, Failure{
							Failure:    fmt.Sprintf("should drop = 0 from declaration of var %s; it is the zero value", name),
							RuleName:   r.Name(),
							Category:   "zero-value",
							Position:   file.NodePosition(valueSpec),
							Confidence: 0.9,
						})
						continue
					}
				}

				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", exprString(valueSpec.Type), name),
					RuleName:   r.Name(),
					Category:   "type-inference",
					Position:   file.NodePosition(valueSpec),
					Confidence: 0.8,
				})
			}
		}
		return true
	})
	return failures
}

func exprString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return exprString(e.X) + "." + e.Sel.Name
	case *ast.StarExpr:
		return "*" + exprString(e.X)
	case *ast.ArrayType:
		return "[]" + exprString(e.Elt)
	default:
		return "type"
	}
}

// 3. ExportedRule
type ExportedRule struct{}

func (r *ExportedRule) Name() string { return "exported" }
func (r *ExportedRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	for _, decl := range file.AST.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					if ast.IsExported(s.Name.Name) && (d.Doc == nil && s.Doc == nil) {
						failures = append(failures, Failure{
							Failure:    fmt.Sprintf("exported type %s should have comment or be unexported", s.Name.Name),
							RuleName:   r.Name(),
							Category:   "comments",
							Position:   file.NodePosition(s.Name),
							Confidence: 1.0,
						})
					}
				case *ast.ValueSpec:
					for _, name := range s.Names {
						if ast.IsExported(name.Name) && (d.Doc == nil && s.Doc == nil) {
							kind := "var"
							if d.Tok == token.CONST {
								kind = "const"
							}
							failures = append(failures, Failure{
								Failure:    fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name),
								RuleName:   r.Name(),
								Category:   "comments",
								Position:   file.NodePosition(name),
								Confidence: 1.0,
							})
						}
					}
				}
			}
		case *ast.FuncDecl:
			if ast.IsExported(d.Name.Name) && d.Doc == nil {
				kind := "function"
				if d.Recv != nil {
					kind = "method"
				}
				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("exported %s %s should have comment or be unexported", kind, d.Name.Name),
					RuleName:   r.Name(),
					Category:   "comments",
					Position:   file.NodePosition(d.Name),
					Confidence: 1.0,
				})
			}
		}
	}
	return failures
}

// 4. DotImportsRule
type DotImportsRule struct{}

func (r *DotImportsRule) Name() string { return "dot-imports" }
func (r *DotImportsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	for _, imp := range file.AST.Imports {
		if imp.Name != nil && imp.Name.Name == "." {
			failures = append(failures, Failure{
				Failure:    "should not use dot imports",
				RuleName:   r.Name(),
				Category:   "imports",
				Position:   file.NodePosition(imp),
				Confidence: 1.0,
			})
		}
	}
	return failures
}

// 5. BlankImportsRule
type BlankImportsRule struct{}

func (r *BlankImportsRule) Name() string { return "blank-imports" }
func (r *BlankImportsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	if file.AST.Name.Name == "main" || strings.HasSuffix(file.Name, "_test.go") {
		return failures
	}

	for _, imp := range file.AST.Imports {
		if imp.Name != nil && imp.Name.Name == "_" {
			if imp.Doc == nil && imp.Comment == nil {
				failures = append(failures, Failure{
					Failure:    "a blank import should be only in a main or test package, or have a comment justifying it",
					RuleName:   r.Name(),
					Category:   "imports",
					Position:   file.NodePosition(imp),
					Confidence: 1.0,
				})
			}
		}
	}
	return failures
}

// 6. UnusedParameterRule
type UnusedParameterRule struct{}

func (r *UnusedParameterRule) Name() string { return "unused-parameter" }
func (r *UnusedParameterRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}

		if fn.Type.Params == nil {
			return true
		}

		usedNames := make(map[string]bool)
		ast.Inspect(fn.Body, func(bn ast.Node) bool {
			if id, ok := bn.(*ast.Ident); ok {
				usedNames[id.Name] = true
			}
			return true
		})

		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				if name.Name != "_" && !strings.HasPrefix(name.Name, "_") {
					if !usedNames[name.Name] {
						failures = append(failures, Failure{
							Failure:    fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
							RuleName:   r.Name(),
							Category:   "bad practice",
							Position:   file.NodePosition(name),
							Confidence: 1.0,
						})
					}
				}
			}
		}
		return true
	})
	return failures
}

// 7. UnusedReceiverRule
type UnusedReceiverRule struct{}

func (r *UnusedReceiverRule) Name() string { return "unused-receiver" }
func (r *UnusedReceiverRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil || fn.Recv == nil || len(fn.Recv.List) == 0 {
			return true
		}

		recvField := fn.Recv.List[0]
		if len(recvField.Names) == 0 {
			return true
		}

		recvName := recvField.Names[0].Name
		if recvName == "_" || strings.HasPrefix(recvName, "_") {
			return true
		}

		used := false
		ast.Inspect(fn.Body, func(bn ast.Node) bool {
			if id, ok := bn.(*ast.Ident); ok && id.Name == recvName {
				used = true
				return false
			}
			return true
		})

		if !used {
			failures = append(failures, Failure{
				Failure:    fmt.Sprintf("method receiver '%s' is not referenced in method's body, consider removing or renaming it as _", recvName),
				RuleName:   r.Name(),
				Category:   "bad practice",
				Position:   file.NodePosition(recvField.Names[0]),
				Confidence: 1.0,
			})
		}
		return true
	})
	return failures
}

// 8. UnreachableCodeRule
type UnreachableCodeRule struct{}

func (r *UnreachableCodeRule) Name() string { return "unreachable-code" }
func (r *UnreachableCodeRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) <= 1 {
			return true
		}

		for i := 0; i < len(block.List)-1; i++ {
			stmt := block.List[i]
			if isTerminatingStmt(stmt) {
				nextStmt := block.List[i+1]
				failures = append(failures, Failure{
					Failure:    "unreachable code after this statement",
					RuleName:   r.Name(),
					Category:   "logic",
					Position:   file.NodePosition(nextStmt),
					Confidence: 1.0,
				})
				break
			}
		}
		return true
	})
	return failures
}

func isTerminatingStmt(stmt ast.Stmt) bool {
	switch s := stmt.(type) {
	case *ast.ReturnStmt, *ast.BranchStmt:
		return true
	case *ast.ExprStmt:
		if call, ok := s.X.(*ast.CallExpr); ok {
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				if id, ok := sel.X.(*ast.Ident); ok && id.Name == "os" && sel.Sel.Name == "Exit" {
					return true
				}
			}
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "panic" {
				return true
			}
		}
	}
	return false
}

// 9. IndentErrorFlowRule
type IndentErrorFlowRule struct{}

func (r *IndentErrorFlowRule) Name() string { return "indent-error-flow" }
func (r *IndentErrorFlowRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}

		if len(ifStmt.Body.List) > 0 {
			lastStmt := ifStmt.Body.List[len(ifStmt.Body.List)-1]
			if isTerminatingStmt(lastStmt) {
				failures = append(failures, Failure{
					Failure:    "if block ends with a return statement, so drop this else and outdent its block",
					RuleName:   r.Name(),
					Category:   "",
					Position:   file.NodePosition(ifStmt.Else),
					Confidence: 1.0,
				})
			}
		}
		return true
	})
	return failures
}

// 10. VarNamingRule
type VarNamingRule struct{}

func (r *VarNamingRule) Name() string { return "var-naming" }
func (r *VarNamingRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		if valSpec, ok := n.(*ast.ValueSpec); ok {
			for _, name := range valSpec.Names {
				if strings.Contains(name.Name, "_") && name.Name != "_" && !strings.HasPrefix(name.Name, "_") {
					suggested := snakeToCamel(name.Name)
					failures = append(failures, Failure{
						Failure:    fmt.Sprintf("don't use underscores in Go names; var %s should be %s", name.Name, suggested),
						RuleName:   r.Name(),
						Category:   "naming",
						Position:   file.NodePosition(name),
						Confidence: 0.9,
					})
				}
			}
		}
		return true
	})
	return failures
}

func snakeToCamel(s string) string {
	parts := strings.Split(s, "_")
	var sb strings.Builder
	for i, p := range parts {
		if i == 0 {
			sb.WriteString(p)
		} else {
			sb.WriteString(strings.Title(p))
		}
	}
	return sb.String()
}

// 11. ErrorStringsRule
type ErrorStringsRule struct{}

func (r *ErrorStringsRule) Name() string { return "error-strings" }
func (r *ErrorStringsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}

		isErrFunc := false
		if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if (id.Name == "errors" && sel.Sel.Name == "New") || (id.Name == "fmt" && sel.Sel.Name == "Errorf") {
					isErrFunc = true
				}
			}
		}

		if isErrFunc {
			if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
				str, err := strconv.Unquote(lit.Value)
				if err == nil && len(str) > 0 {
					firstRune := []rune(str)[0]
					lastRune := []rune(str)[len([]rune(str))-1]
					if unicode.IsUpper(firstRune) || lastRune == '.' || lastRune == '!' || lastRune == '\n' {
						failures = append(failures, Failure{
							Failure:    "error strings should not be capitalized or end with punctuation or a newline",
