// 13. BoolLiteralInExprRule
type BoolLiteralInExprRule struct{}

func (r *BoolLiteralInExprRule) Name() string { return "bool-literal-in-expr" }
func (r *BoolLiteralInExprRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}

		if bin.Op == token.EQL || bin.Op == token.NEQ {
			if isBoolLit(bin.X) || isBoolLit(bin.Y) {
				failures = append(failures, Failure{
					Failure:    "omit Boolean literal in expression",
					RuleName:   r.Name(),
					Category:   "style",
					Position:   file.NodePosition(bin),
					Confidence: 1.0,
				})
			}
		}
		return true
	})
	return failures
}

func isBoolLit(expr ast.Expr) bool {
	if id, ok := expr.(*ast.Ident); ok && (id.Name == "true" || id.Name == "false") {
		return true
	}
	return false
}

