				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("should replace %s %s 1 with %s%s", lhsStr, assign.Tok, lhsStr, op),
					RuleName:   r.Name(),
					Category:   "unary-op",
					Position:   file.NodePosition(assign),
					Confidence: 0.8,
				})
			}
		}
		return true
