// 18. RangeValInClosureRule
type RangeValInClosureRule struct{}

func (r *RangeValInClosureRule) Name() string { return "range-val-in-closure" }
func (r *RangeValInClosureRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		forStmt, ok := n.(*ast.RangeStmt)
		if !ok || forStmt.Body == nil {
			return true
		}

		var rangeVars []string
		if id, ok := forStmt.Key.(*ast.Ident); ok && id.Name != "_" {
			rangeVars = append(rangeVars, id.Name)
		}
		if id, ok := forStmt.Value.(*ast.Ident); ok && id.Name != "_" {
			rangeVars = append(rangeVars, id.Name)
		}

		if len(rangeVars) == 0 {
			return true
		}

		ast.Inspect(forStmt.Body, func(bn ast.Node) bool {
			funcLit, ok := bn.(*ast.FuncLit)
			if !ok || funcLit.Body == nil {
				return true
			}

			ast.Inspect(funcLit.Body, func(fn ast.Node) bool {
				if id, ok := fn.(*ast.Ident); ok {
					for _, rv := range rangeVars {
						if id.Name == rv {
							failures = append(failures, Failure{
								Failure:    fmt.Sprintf("loop variable %s captured by func literal", rv),
								RuleName:   r.Name(),
								Category:   "",
								Position:   file.NodePosition(id),
								Confidence: 1.0,
							})
						}
					}
				}
				return true
			})
			return true
		})
		return true
	})
	return failures
}

// 19. UnnecessaryStmtRule
type UnnecessaryStmtRule struct{}

func (r *UnnecessaryStmtRule) Name() string { return "unnecessary-stmt" }
func (r *UnnecessaryStmtRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.SwitchStmt:
			if s.Body != nil && len(s.Body.List) == 1 {
				failures = append(failures, Failure{
					Failure:    "switch with only one case can be replaced by an if-then",
					RuleName:   r.Name(),
					Category:   "style",
					Position:   file.NodePosition(s),
					Confidence: 1.0,
				})
			}
		case *ast.CaseClause:
			if len(s.Body) > 0 {
				lastStmt := s.Body[len(s.Body)-1]
				if branch, ok := lastStmt.(*ast.BranchStmt); ok && branch.Tok == token.BREAK {
					failures = append(failures, Failure{
						Failure:    "omit unnecessary break at the end of case clause",
						RuleName:   r.Name(),
						Category:   "style",
						Position:   file.NodePosition(branch),
						Confidence: 1.0,
					})
				}
			}
		}
		return true
	})
	return failures
}

