		if count > limit {
			failures = append(failures, Failure{
				Failure:    fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", limit, count),
				RuleName:   r.Name(),
				Category:   "",
				Position:   file.NodePosition(fn.Name),
				Confidence: 1.0,
			})
		}
		return true
	})
	return failures
}

