		typeCounts := make(map[string]int)
		unnamed := false
		for _, res := range fn.Type.Results.List {
			if len(res.Names) == 0 {
				unnamed = true
			}
			tStr := exprString(res.Type)
			typeCounts[tStr]++
		}

		if unnamed {
			for _, count := range typeCounts {
				if count > 1 {
					failures = append(failures, Failure{
						Failure:    "unnamed results of the same type may be confusing, consider using named results",
						RuleName:   r.Name(),
						Category:   "naming",
						Position:   file.NodePosition(fn.Name),
						Confidence: 1.0,
					})
					break
				}
			}
		}
		return true
	})
	return failures
}

type ConstantLogicalExprRule struct{}

func (r *ConstantLogicalExprRule) Name() string { return "constant-logical-expr" }
func (r *ConstantLogicalExprRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}

		if isBoolLit(bin.X) && isBoolLit(bin.Y) {
			failures = append(failures, Failure{
				Failure:    "expression always evaluates to true",
				RuleName:   r.Name(),
				Category:   "logic",
				Position:   file.NodePosition(bin),
				Confidence: 1.0,
			})
		}
		return true
	})
	return failures
}

