type ReceiverNamingRule struct{}

func (r *ReceiverNamingRule) Name() string { return "receiver-naming" }
func (r *ReceiverNamingRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	receivers := make(map[string]string)
	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
			return true
		}

		recvField := fn.Recv.List[0]
		if len(recvField.Names) == 0 {
			return true
		}

		recvName := recvField.Names[0].Name
		typeName := exprString(recvField.Type)

		if prev, ok := receivers[typeName]; ok {
			if prev != recvName {
				failures = append(failures, Failure{
					Failure:    fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", recvName, prev, typeName),
					RuleName:   r.Name(),
					Category:   "naming",
					Position:   file.NodePosition(recvField.Names[0]),
					Confidence: 1.0,
				})
			}
		} else {
			receivers[typeName] = recvName
		}
		return true
	})
	return failures
}

type ModifiesValueReceiverRule struct{}

func (r *ModifiesValueReceiverRule) Name() string { return "modifies-value-receiver" }
func (r *ModifiesValueReceiverRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 || fn.Body == nil {
			return true
		}

		recvField := fn.Recv.List[0]
		if _, ok := recvField.Type.(*ast.StarExpr); ok {
			return true // pointer receiver is fine
		}

		if len(recvField.Names) == 0 {
			return true
		}
		recvName := recvField.Names[0].Name

		ast.Inspect(fn.Body, func(bn ast.Node) bool {
			assign, ok := bn.(*ast.AssignStmt)
			if !ok {
				return true
			}
			for _, lhs := range assign.Lhs {
				if sel, ok := lhs.(*ast.SelectorExpr); ok {
					if id, ok := sel.X.(*ast.Ident); ok && id.Name == recvName {
						failures = append(failures, Failure{
							Failure:    "suspicious assignment to a by-value method receiver",
							RuleName:   r.Name(),
							Category:   "",
							Position:   file.NodePosition(assign),
							Confidence: 1.0,
						})
					}
				}
			}
			return true
		})
		return true
	})
	return failures
}

type StringOfIntRule struct{}

func (r *StringOfIntRule) Name() string { return "string-of-int" }
func (r *StringOfIntRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}

		if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "string" {
			if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.INT {
				failures = append(failures, Failure{
					Failure:    "dubious conversion of an integer into a string, use strconv.Itoa",
					RuleName:   r.Name(),
					Category:   "",
					Position:   file.NodePosition(call),
					Confidence: 1.0,
				})
			}
		}
		return true
	})
	return failures
}

type ConfusingResultsRule struct{}

func (r *ConfusingResultsRule) Name() string { return "confusing-results" }
func (r *ConfusingResultsRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type.Results == nil || len(fn.Type.Results.List) <= 1 {
			return true
		}

		typeCounts := make(map[string]int)
		unnamed := false
		for _, res := range fn.Type.Results.List {
			if len(res.Names) == 0 {
				unnamed = true
			}
			tStr := exprString(res.Type)
			typeCounts[tStr]++
		}

		if unnamed {
			for _, count := range typeCounts {
				if count > 1 {
					failures = append(failures, Failure{
						Failure:    "unnamed results of the same type may be confusing, consider using named results",
						RuleName:   r.Name(),
						Category:   "naming",
						Position:   file.NodePosition(fn.Name),
						Confidence: 1.0,
					})
					break
				}
			}
		}
		return true
	})
	return failures
}

type ConstantLogicalExprRule struct{}

func (r *ConstantLogicalExprRule) Name() string { return "constant-logical-expr" }
func (r *ConstantLogicalExprRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}

		if isBoolLit(bin.X) && isBoolLit(bin.Y) {
			failures = append(failures, Failure{
				Failure:    "expression always evaluates to true",
				RuleName:   r.Name(),
				Category:   "logic",
				Position:   file.NodePosition(bin),
				Confidence: 1.0,
			})
		}
		return true
	})
	return failures
}

type ContextAsArgumentRule struct{}

func (r *ContextAsArgumentRule) Name() string { return "context-as-argument" }
func (r *ContextAsArgumentRule) Apply(file *File, args []interface{}) []Failure {
	var failures []Failure
	if file.AST == nil {
		return failures
	}

	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type.Params == nil || len(fn.Type.Params.List) <= 1 {
			return true
		}

		for i, param := range fn.Type.Params.List {
			if i > 0 {
				tStr := exprString(param.Type)
				if tStr == "context.Context" || tStr == "Context" {
					failures = append(failures, Failure{
						Failure:    "context.Context should be the first parameter of a function",
						RuleName:   r.Name(),
						Category:   "arg-order",
						Position:   file.NodePosition(param),
						Confidence: 0.9,
					})
				}
			}
		}
		return true
	})
	return failures
}

